std::vector<int> A = {10, 20, 30, 40};
std::vector<int> B = {20, 40, 50, 60};
std::vector<int> C;

C.reserve(A.size() + B.size());

// Calculates the union of A and B, storing results in C
std::set_union(
    A.begin(), A.end(),
    B.begin(), B.end(),
    std::back_inserter(C)
);

// C is now {10, 20, 30, 40, 50, 60}
// Returns iterator to the end of the constructed range
